import json,random,secrets,html,re
from pathlib import Path
D=Path('artifacts/rerun-v6');rows=json.loads((D/'final.json').read_text(encoding='utf-8'));esc=lambda x:html.escape(str(x or ''))
assert len(rows)==25 and all(x['review_state']=='draft' and x['article'] for x in rows)
stats={'regenerated':len(rows),'fact_passed':sum(x['article']['fact_check']['count']==0 for x in rows),'fact_findings':sum(x['article']['fact_check']['count'] for x in rows),'fact_red_articles':sum(bool(x['article']['fact_check'].get('review_alert')) for x in rows),'meta_remaining':sum(x['article']['editorial_check']['meta_count'] for x in rows),'markdown_remaining':sum(x['article']['editorial_check']['markdown_count'] for x in rows),'ai_findings':sum(x['article']['ai_review']['count'] for x in rows),'ai_needs_check':sum(x['article']['ai_review']['state']!='complete' for x in rows),'ai_flagged_articles':sum(bool(x['article']['ai_review']['count']) for x in rows),'meta_hits_manual_expanded_check':2}
stats['fact_pass_rate']=stats['fact_passed']/len(rows);stats['fact_average']=stats['fact_findings']/len(rows)
(D/'summary.json').write_text(json.dumps(stats,ensure_ascii=False,indent=2),encoding='utf-8')
langs={'AF':'en','AR':'ar','BR':'pt','ID':'id','JP':'ja','KR':'ko','LA':'es','MY':'en','SA':'en','TH':'th','TW':'zh','VN':'vi'}
selection=D/'sample-selection.json'
if selection.exists(): selected=[next(x for x in rows if x['id']==i) for i in json.loads(selection.read_text())['ids']]
else:
 seed=secrets.randbits(64);rng=random.Random(seed);pool=rows[:];rng.shuffle(pool);selected=[];seen=set()
 for x in pool:
  lang=langs[x['region_code']]
  if lang not in seen:selected.append(x);seen.add(lang)
  if len(selected)==3:break
 selection.write_text(json.dumps({'seed':seed,'method':'shuffle articles, first three distinct languages; no quality filtering','ids':[x['id'] for x in selected],'regions':[x['region_code'] for x in selected]},indent=2),encoding='utf-8')
style='''body{font:16px/1.8 system-ui,sans-serif;background:#f4f6f9;color:#172235;margin:0}main{max-width:960px;margin:36px auto;padding:0 20px}article,section{background:white;border:1px solid #dae0e8;border-radius:14px;padding:28px;margin:24px 0;overflow-wrap:anywhere}h1,h2{line-height:1.4}h1{font-size:28px}h2{font-size:24px}aside{border-top:1px solid #ddd;margin-top:28px;padding-top:16px}small{color:#526171}.warning{background:#fff5d5;padding:12px}.summary{background:#edf3f9;padding:16px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{border:1px solid #ddd;padding:8px;text-align:left}a{color:#1467b0}@media(max-width:600px){main{padding:0 12px}article,section{padding:18px}h1{font-size:24px}h2{font-size:21px}}'''
def page(title,content):return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><style>'+style+'</style><main><h1>'+esc(title)+'</h1>'+content+'</main></html>'
cards=[]
for x in selected:
 a=x['article'];f=a['fact_check'];e=a['editorial_check'];v=a['ai_review'];body=a.get('article_content',a['content']);sources=''.join('<li><a target="_blank" rel="noopener" href="'+esc(s['url'])+'">'+esc(s.get('source_name') or s['url'])+'</a></li>' for s in a.get('sources',[]) if s['url'].startswith(('http://','https://')))
 issues=''.join('<li>'+esc(i['field'])+'：<mark>'+esc(i['text'])+'</mark> — '+esc(i['reason'])+'</li>' for i in f['findings']);ai=''.join('<li><blockquote>'+esc(i['quote'])+'</blockquote>'+esc(i['reason'])+'</li>' for i in v['issues'])
 cards.append('<article><small>'+esc(x['region_code']+' / '+langs[x['region_code']])+' · 待审 · DeepSeek Flash · 写稿 $'+f"{a['writer_usage']['estimated_cost_usd']:.6f}"+'</small><h2>'+esc(a['title'])+'</h2><p class="summary">'+esc(a['summary'])+'</p><p class="warning">事实核查：'+str(f['count'])+' 处未匹配；AI 审核：'+str(v['count'])+' 项疑点。检查结果不等同于已证实错误。</p><div lang="'+langs[x['region_code']]+'" dir="'+('rtl' if langs[x['region_code']]=='ar' else 'auto')+'">'+body+'</div><aside><b>系统附加参考链接（不属于正文）</b><ul>'+sources+'</ul></aside><aside><b>事实匹配详情</b><ul>'+issues+'</ul><b>AI 审核详情</b><ul>'+ai+'</ul></aside></article>')
